/*selectSolbCost*/
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'C020'				
AND		FLAG = 'Y'
AND		COMPANY_CODE = #{st_buyer}
AND		CODE		 = #{st_code}


/*selectSolbAccount*/
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'M014'
AND		FLAG = 'Y'
AND 	COMPANY_CODE = #{st_buyer}
AND		CODE		 = #{st_code}


/*selectSolbPlant*/
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'C031'
AND		FLAG = 'Y'
AND 	COMPANY_CODE = #{st_buyer}
AND		CODE		 = #{st_code}
